def band(score: int) -> str:
    if score >= 85:
        return "Strong"
    if score >= 70:
        return "Moderate"
    return "Attention Needed"

def skin_report(score: int, note: str = "") -> dict:
    if score < 70:
        issues = ["Sensitivity / barrier weakness", "Glow imbalance"]
        services = ["Calming facial", "Barrier-repair serum plan"]
        warning = "Patch test advised before active treatments."
        homecare = "Use ceramide moisturizer, gentle cleanser, and SPF."
    elif score < 85:
        issues = ["Mild dehydration", "Uneven glow"]
        services = ["Hydration facial", "Brightening maintenance"]
        warning = "No critical warning."
        homecare = "Use SPF, hydration serum, and weekly mask."
    else:
        issues = ["Healthy skin baseline"]
        services = ["Glow maintenance facial", "Pre-event radiance ritual"]
        warning = "No critical warning."
        homecare = "Maintain hydration and sunscreen routine."
    return {"title":"Skin Analysis Report","health_index":score,"band":band(score),"issues":issues,"warning":warning,"services":services,"homecare":homecare,"note":note}

def hair_report(score: int, note: str = "") -> dict:
    if score < 70:
        issues = ["Hair fall / breakage risk", "Scalp imbalance likely"]
        services = ["Scalp therapy", "Protein repair plan"]
        warning = "Trichology caution if shedding is persistent."
        homecare = "Use mild shampoo, scalp serum, and avoid heat stress."
    elif score < 85:
        issues = ["Dryness or dullness", "Mid-length care needed"]
        services = ["Protein spa", "Scalp balancing ritual"]
        warning = "No critical warning."
        homecare = "Use serum on lengths and heat protection."
    else:
        issues = ["Good strength and manageable scalp health"]
        services = ["Gloss spa", "Color-safe shine ritual"]
        warning = "No critical warning."
        homecare = "Maintain regular spa and color-safe cleansing."
    return {"title":"Hair Analysis Report","health_index":score,"band":band(score),"issues":issues,"warning":warning,"services":services,"homecare":homecare,"note":note}

def foot_report(score: int, note: str = "") -> dict:
    if score < 70:
        issues = ["Heel crack risk", "Barrier dryness / pressure concern"]
        services = ["Repair pedicure", "Protective foot care plan"]
        warning = "Escalate if diabetic foot or pain symptoms are reported."
        homecare = "Use heel balm nightly and avoid harsh scrubs."
    elif score < 85:
        issues = ["Dry heel tendency", "Maintenance pedicure required"]
        services = ["Repair pedicure", "Heel softening therapy"]
        warning = "No critical warning."
        homecare = "Use regular hydration and closed-toe protection in dusty areas."
    else:
        issues = ["Healthy foot-care baseline"]
        services = ["Luxury pedicure", "Hydration maintenance"]
        warning = "No critical warning."
        homecare = "Maintain weekly hydration and hygiene routine."
    return {"title":"Foot Analysis Report","health_index":score,"band":band(score),"issues":issues,"warning":warning,"services":services,"homecare":homecare,"note":note}

def saree_bridal_plan(color: str, event_time: str) -> dict:
    c = (color or "").lower().strip()
    t = (event_time or "").lower().strip()
    if "maroon" in c:
        palette = "Deep maroon, antique gold, and muted rose highlights"
        jewelry = "Temple jewelry or antique kundan"
        hair = "Soft low bun with jasmine or textured bridal waves"
    elif "green" in c:
        palette = "Emerald glow with warm gold accents"
        jewelry = "Polki or emerald-finish jewelry"
        hair = "Braided bun with side volume"
    else:
        palette = "Classic bridal tones with gold and soft rose balance"
        jewelry = "Kundan / stone-work mix"
        hair = "Polished bridal bun or Hollywood waves"
    makeup = "Richer eye depth and long-wear matte base for evening lights." if ("evening" in t or "night" in t) else "Radiant base, fresh blush, and softer highlight for daylight photography."
    return {"palette":palette,"jewelry":jewelry,"hair":hair,"makeup":makeup,"looks":["Priority Look 1: Signature bridal glam","Priority Look 2: Soft luxe glow","Priority Look 3: Traditional regal finish"]}

def chatbot_reply(message: str, language: str = "en") -> dict:
    low = (message or "").strip().lower()
    if any(k in low for k in ["book","appointment","slot","calendar"]):
        expression="happy"; en="I can help with booking guidance. Tell me the service, date, and time, and I’ll suggest the best slot and prep notes."; ta="புக்கிங் உதவி செய்யலாம். சேவை, தேதி, நேரம் சொல்லுங்கள்; சரியான ஸ்லாட் மற்றும் தயாரிப்பு குறிப்புகளை சொல்கிறேன்."
    elif any(k in low for k in ["hair fall","dandruff","scalp","hair","color"]):
        expression="thoughtful"; en="For hair guidance, share the concern, recent treatments, and hair texture. I can suggest salon services and aftercare."; ta="முடி பிரச்சினைக்கு உங்கள் concern, recent treatments, hair texture சொன்னால் service மற்றும் aftercare சொல்கிறேன்."
    elif any(k in low for k in ["skin","facial","glow","acne","pigment"]):
        expression="thoughtful"; en="For skin guidance, tell me if the concern is acne, dullness, tanning, or sensitivity. I’ll suggest salon services and home-care."; ta="Skin guidance க்கு acne, dullness, tanning, sensitivity எது என்பதை சொல்லுங்கள். அதன்படி service மற்றும் home-care சொல்கிறேன்."
    elif any(k in low for k in ["foot","pedicure","heel","crack"]):
        expression="care"; en="For foot care, I’ll check dryness, heel cracks, and pressure discomfort. I can suggest pedicure therapy and caution notes."; ta="Foot care க்கு dryness, heel crack, pressure discomfort பார்க்கலாம். Pedicure therapy மற்றும் caution notes தருகிறேன்."
    elif any(k in low for k in ["bridal","saree","wedding","makeup"]):
        expression="happy"; en="For bridal planning, tell me the saree color, ceremony time, and whether you want classic, regal, or soft glam styling."; ta="Bridal plan க்கு saree color, function time, classic / regal / soft glam style எது வேண்டும் என்று சொல்லுங்கள்."
    else:
        expression="smile"; en="I’m your stylist assistant. Ask about hair, skin, bridal looks, booking support, or Tamil replies."; ta="நான் உங்கள் stylist assistant. Hair, skin, bridal looks, booking support அல்லது தமிழ் replies பற்றி கேளுங்கள்."
    return {"reply": ta if language == "ta" else en, "expression": expression}

@app.get("/assistant-image.png")
def assistant_image():
    return Response(content=ASSISTANT_IMAGE_BYTES, media_type="image/png")

@app.get("/favicon.ico")
def favicon():
    return Response(status_code=204)

@app.post("/api/chat")
def api_chat(req: ChatRequest):
    return chatbot_reply(req.message, req.language or "en")

@app.post("/api/analyze/skin")
def api_skin(req: AnalyzerRequest):
    return skin_report(int(req.score), req.note or "")

@app.post("/api/analyze/hair")
def api_hair(req: AnalyzerRequest):
    return hair_report(int(req.score), req.note or "")

@app.post("/api/analyze/foot")
def api_foot(req: AnalyzerRequest):
    return foot_report(int(req.score), req.note or "")

@app.get("/api/bridal")
def api_bridal(color: str = "maroon", event_time: str = "evening"):
    return saree_bridal_plan(color, event_time)

@app.get("/api/incidents")
def api_incidents():
    return INCIDENTS

@app.get("/api/legal")
def api_legal():
    return LEGAL_CASES

@app.get("/api/certifications")
def api_certifications():
    return CERTIFICATIONS

@app.get("/api/iot")
def api_iot():
    return IOT_MONITORS

@app.get("/api/hair-health")
def api_hair_health():
    return HAIR_HEALTH_RECORDS

@app.get("/api/franchise")
def api_franchise():
    return {"branches": BRANCH_PERFORMANCE}

HTML = r"""
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ezhil-Sigai by Naturals</title>
<style>
:root{
  --bg:#070b16; --panel:#10192b; --panel2:#0c1323; --line:rgba(255,255,255,.08);
  --text:#eef2ff; --muted:#a6b0d4; --accent:#7b1934; --accent2:#a72d4f; --soft:#f1c8d3;
  --good:#44d19f; --shadow:0 18px 42px rgba(0,0,0,.34);
}
*{box-sizing:border-box}
body{margin:0;font-family:Inter,Segoe UI,Arial,sans-serif;background:radial-gradient(circle at top left,#151f39 0%,#091120 45%,#040813 100%);color:var(--text)}
.app{display:grid;grid-template-columns:250px 1fr;min-height:100vh}
.sidebar{position:sticky;top:0;height:100vh;padding:20px 16px;background:linear-gradient(180deg,#0f1527,#09101c);border-right:1px solid var(--line)}
.brandrow{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.logo{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,#7b1934,#c45779);display:flex;align-items:center;justify-content:center;box-shadow:0 12px 24px rgba(123,25,52,.28)}
.logo svg{width:24px;height:24px}
.brandname{font-size:24px;font-weight:800}
.sidebar-note{color:var(--muted);font-size:13px;line-height:1.55;margin-bottom:20px}
.nav-btn{width:100%;text-align:left;padding:12px 14px;border-radius:14px;border:1px solid transparent;background:transparent;color:#dbe3ff;cursor:pointer;margin-bottom:10px;font-size:14px}
.nav-btn:hover,.nav-btn.active{background:rgba(167,45,79,.16);border-color:rgba(241,200,211,.16);color:#fff}
.main{padding:22px}
.top{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:18px}
.titlewrap{text-align:center;flex:1}
.title{font-size:30px;font-weight:800}
.subtitle{font-size:14px;color:var(--soft);margin-top:4px}
.pill{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid var(--line);border-radius:999px;background:rgba(255,255,255,.03);font-size:12px;color:var(--muted)}
.dot{width:8px;height:8px;border-radius:999px;background:var(--good)}
.grid{display:grid;gap:16px}.grid-4{grid-template-columns:repeat(4,minmax(0,1fr))}.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--line);border-radius:20px;padding:18px;box-shadow:var(--shadow)}
.kpi-label{font-size:13px;color:var(--muted)} .kpi-value{font-size:36px;font-weight:800;margin-top:8px}
.section-title{font-size:19px;font-weight:800;margin-bottom:6px}
.hidden{display:none}
.table{width:100%;border-collapse:collapse;font-size:14px}
.table th,.table td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line);vertical-align:top}
.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
label{display:block;font-size:13px;color:var(--muted);margin-bottom:6px}
input,select{width:100%;padding:12px 14px;border-radius:14px;border:1px solid var(--line);background:#0b1325;color:#fff;outline:none;font-size:14px}
.btn{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;border:none;border-radius:14px;padding:12px 16px;font-weight:700;cursor:pointer}
.report{margin-top:14px;padding:16px;border-radius:16px;border:1px solid var(--line);background:rgba(255,255,255,.03);line-height:1.75;font-size:14px}
.mini-list{font-size:14px;line-height:1.75;color:#dfe6ff}.mini-list .item{padding:10px 0;border-bottom:1px solid var(--line)}
.spark{height:8px;border-radius:999px;background:rgba(255,255,255,.06);overflow:hidden;margin-top:10px}.spark>span{display:block;height:100%;background:linear-gradient(90deg,var(--soft),var(--accent2))}
.chat-launcher{position:fixed;right:24px;bottom:24px;width:74px;height:74px;border:none;border-radius:999px;cursor:pointer;background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;font-size:30px;box-shadow:0 18px 44px rgba(123,25,52,.42);z-index:40}
.chat-popup{position:fixed;right:24px;bottom:110px;width:620px;max-width:calc(100vw - 28px);background:linear-gradient(180deg,#11172b,#0a1020);border:1px solid var(--line);border-radius:24px;overflow:hidden;box-shadow:var(--shadow);display:none;z-index:41}
.chat-popup.open{display:block}
.chat-head{padding:16px;display:grid;grid-template-columns:260px 1fr 40px;gap:14px;align-items:start;border-bottom:1px solid var(--line);background:linear-gradient(180deg,rgba(167,45,79,.16),rgba(167,45,79,.06))}
.close{width:38px;height:38px;border-radius:999px;border:1px solid var(--line);background:transparent;color:#fff;cursor:pointer}
.assistant-frame{width:260px;height:360px;position:relative;overflow:hidden;border-radius:20px;border:1px solid rgba(255,255,255,.12);box-shadow:0 16px 38px rgba(0,0,0,.38);background:linear-gradient(180deg,#25161d,#130f1a);transition:transform .25s ease, box-shadow .25s ease, filter .25s ease}
.assistant-frame img{width:100%;height:100%;object-fit:contain;object-position:center center;display:block;padding:8px}
.assistant-frame::before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.08),transparent 24%,transparent 76%,rgba(0,0,0,.08));pointer-events:none}
.assistant-frame::after{content:"";position:absolute;left:12%;right:12%;bottom:8px;height:18px;background:radial-gradient(ellipse at center,rgba(255,255,255,.18),rgba(255,255,255,0));filter:blur(5px);pointer-events:none}
.blink-layer{position:absolute;left:28%;right:28%;top:22%;height:11%;background:linear-gradient(180deg,rgba(138,88,78,.86),rgba(188,136,116,.82));border-radius:999px;transform-origin:center top;transform:scaleY(0);opacity:0;pointer-events:none;animation:blink 5.6s infinite}
@keyframes blink{0%,45%,47%,100%{transform:scaleY(0);opacity:0}46%{transform:scaleY(1);opacity:.72}}
.assistant-frame.smile{animation:floaty 3.2s ease-in-out infinite}
@keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.assistant-frame.happy{transform:scale(1.03);box-shadow:0 18px 42px rgba(167,45,79,.34);filter:saturate(1.08)}
.assistant-frame.thoughtful{filter:saturate(.94) brightness(.97)}
.assistant-frame.care{box-shadow:0 18px 42px rgba(241,200,211,.18)}
.chat-status{font-size:12px;color:var(--soft);margin-top:6px;line-height:1.45}
.chat-body{height:320px;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:12px}
.bubble{max-width:84%;padding:12px 14px;border-radius:18px;line-height:1.6;font-size:14px}
.bot{align-self:flex-start;background:rgba(255,255,255,.05);border:1px solid var(--line)}
.user{align-self:flex-end;background:linear-gradient(135deg,var(--accent),var(--accent2))}
.chat-input{padding:14px;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 92px;gap:10px}
.lang-row{display:flex;gap:8px;margin-top:8px}
.lang-row button{background:transparent;border:1px solid var(--line);color:#fff;border-radius:999px;padding:6px 12px;cursor:pointer}
.lang-row button.active{background:rgba(241,200,211,.16)}
@media (max-width:980px){.app{grid-template-columns:1fr}.sidebar{position:relative;height:auto;border-right:none;border-bottom:1px solid var(--line)}.grid-4,.grid-3,.grid-2,.form-grid{grid-template-columns:1fr}.chat-head{grid-template-columns:1fr}.assistant-frame{width:100%;height:420px}}
</style>
</head>
<body>
<div class="app">
  <aside class="sidebar">
    <div class="brandrow">
      <div class="logo">
        <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M12 4c1.5 2.4 1.9 4.7 1.2 6.9 2.2-1.4 4.4-1.7 6.6-.9-1.2 2.7-3 4.7-5.5 5.8-1.2.5-2.3.8-3.3.8s-2.2-.3-3.3-.8c-2.5-1.1-4.3-3.1-5.5-5.8 2.2-.8 4.4-.5 6.6.9C8.1 8.7 8.5 6.4 10 4h2z" fill="white"/>
        </svg>
      </div>
      <div class="brandname">Naturals</div>
    </div>
    <div class="sidebar-note">The beauty salon</div>
    <button class="nav-btn active" onclick="showTab('dashboard', this)">Dashboard</button>
    <button class="nav-btn" onclick="showTab('skin', this)">Skin Analyzer</button>
    <button class="nav-btn" onclick="showTab('hair', this)">Hair Analyzer</button>
    <button class="nav-btn" onclick="showTab('foot', this)">Foot Analyzer</button>
    <button class="nav-btn" onclick="showTab('bridal', this)">Bridal Planner</button>
    <button class="nav-btn" onclick="showTab('ops', this)">Safety & Ops</button>
    <button class="nav-btn" onclick="showTab('growth', this)">Growth</button>
    <button class="nav-btn" onclick="showTab('records', this)">Records</button>
  </aside>

  <main class="main">
    <section id="dashboard" class="tab">
      <div class="top">
        <div style="width:90px"></div>
        <div class="titlewrap">
          <div class="title">Ezhil-Sigai by Naturals</div>
          <div class="subtitle">Intelligent Care for Every Strand</div>
        </div>
        <div class="pill"><span class="dot"></span>Live demo mode</div>
      </div>

      <div class="grid grid-4">
        <div class="panel"><div class="kpi-label">Skin Avg</div><div class="kpi-value">86.4</div><div class="spark"><span style="width:86%"></span></div></div>
        <div class="panel"><div class="kpi-label">Hair Avg</div><div class="kpi-value">82.7</div><div class="spark"><span style="width:83%"></span></div></div>
        <div class="panel"><div class="kpi-label">Foot Avg</div><div class="kpi-value">79.1</div><div class="spark"><span style="width:79%"></span></div></div>
        <div class="panel"><div class="kpi-label">Public Safety</div><div class="kpi-value">74</div><div class="spark"><span style="width:74%"></span></div></div>
      </div>

      <div class="grid grid-3" style="margin-top:16px">
        <div class="panel"><div class="section-title">Core Intelligence</div><div class="mini-list"><div class="item">Skin, hair, and foot analyzers</div><div class="item">Professional reports and suggestions</div><div class="item">Popup-only chatbot assistant</div></div></div>
        <div class="panel"><div class="section-title">Bridal Planner</div><div class="mini-list"><div class="item">Saree analyzer</div><div class="item">3 bridal look priorities</div><div class="item">Jewelry and hairstyle notes</div></div></div>
        <div class="panel"><div class="section-title">Growth Goals</div><div class="mini-list"><div class="item">Map L1 → L3 skill paths</div><div class="item">Link quality to revenue</div><div class="item">Predict future skill gaps</div></div></div>
      </div>
    </section>

    <section id="skin" class="tab hidden"><div class="section-title">Skin Analyzer</div><div class="panel"><div class="form-grid"><div><label>Skin score</label><input id="skinScore" type="number" min="0" max="100" value="82"></div><div style="grid-column:span 2"><label>Notes</label><input id="skinNote" placeholder="dullness, sensitivity, tanning"></div></div><div style="margin-top:14px"><button class="btn" onclick="runAnalyzer('skin')">Generate Skin Report</button></div><div id="skinReport" class="report hidden"></div></div></section>
    <section id="hair" class="tab hidden"><div class="section-title">Hair Analyzer</div><div class="panel"><div class="form-grid"><div><label>Hair score</label><input id="hairScore" type="number" min="0" max="100" value="74"></div><div style="grid-column:span 2"><label>Notes</label><input id="hairNote" placeholder="hair fall, scalp itch, frizz"></div></div><div style="margin-top:14px"><button class="btn" onclick="runAnalyzer('hair')">Generate Hair Report</button></div><div id="hairReport" class="report hidden"></div></div></section>
    <section id="foot" class="tab hidden"><div class="section-title">Foot Analyzer</div><div class="panel"><div class="form-grid"><div><label>Foot score</label><input id="footScore" type="number" min="0" max="100" value="68"></div><div style="grid-column:span 2"><label>Notes</label><input id="footNote" placeholder="cracked heels, pain, dryness"></div></div><div style="margin-top:14px"><button class="btn" onclick="runAnalyzer('foot')">Generate Foot Report</button></div><div id="footReport" class="report hidden"></div></div></section>
    <section id="bridal" class="tab hidden"><div class="section-title">Bridal Planner</div><div class="panel"><div class="form-grid"><div><label>Saree color</label><input id="sareeColor" value="Maroon"></div><div><label>Event time</label><select id="eventTime"><option>Morning</option><option selected>Evening</option><option>Night</option></select></div><div><label>Style mood</label><input id="bridalMood" value="Regal"></div></div><div style="margin-top:14px"><button class="btn" onclick="runBridal()">Generate Bridal Plan</button></div><div id="bridalReport" class="report hidden"></div></div></section>
    <section id="ops" class="tab hidden"><div class="grid grid-2"><div class="panel"><div class="section-title">Safety Incidents</div><table class="table" id="incidentTable"></table></div><div class="grid"><div class="panel"><div class="section-title">Legal Cases</div><div id="legalList" class="mini-list"></div></div><div class="panel"><div class="section-title">IoT Monitors</div><div id="iotList" class="mini-list"></div></div></div></div></section>
    <section id="growth" class="tab hidden"><div class="grid grid-2"><div class="panel"><div class="section-title">Strategic Focus</div><div class="mini-list"><div class="item">Convert training into actionable insights</div><div class="item">Map skill level to quality and revenue</div><div class="item">Enable structured branch growth</div></div></div><div class="panel"><div class="section-title">Revenue & Feedback</div><div class="mini-list"><div class="item">Average feedback: 4.53 / 5</div><div class="item">Rising revenue index across review periods</div><div class="item">Premium service quality improves conversion</div></div></div></div><div class="panel" style="margin-top:16px"><div class="section-title">Branch Skill-Gap Map</div><table class="table" id="branchTable"></table></div></section>
    <section id="records" class="tab hidden"><div class="grid grid-2"><div class="panel"><div class="section-title">Certification Records</div><div id="certList" class="mini-list"></div></div><div class="panel"><div class="section-title">Hair Health Records</div><div id="hairHealthList" class="mini-list"></div></div></div></section>
  </main>
</div>

<button class="chat-launcher" onclick="toggleChat()" title="Open stylist chat">✂</button>

<div id="chatPopup" class="chat-popup">
  <div class="chat-head">
    <div class="assistant-frame smile" id="assistantFrame">
      <img src="/assistant-image.png" alt="Chatbot assistant">
      <div class="blink-layer"></div>
    </div>
    <div>
      <div style="font-weight:800">Salon Stylist Assistant</div>
      <div class="chat-status" id="chatStatus">Using your uploaded assistant image with reactive styling.</div>
      <div class="lang-row">
        <button id="langEn" class="active" onclick="setLang('en')">English</button>
        <button id="langTa" onclick="setLang('ta')">தமிழ்</button>
      </div>
    </div>
    <button class="close" onclick="toggleChat()">×</button>
  </div>
  <div id="chatBody" class="chat-body"></div>
  <div class="chat-input">
    <input id="chatMessage" placeholder="Ask about hair, skin, bridal, booking, or aftercare">
    <button class="btn" onclick="sendChat()">Send</button>
  </div>
</div>

<script>
let currentLang = 'en';
function showTab(id, el) {
  document.querySelectorAll('.tab').forEach(x => x.classList.add('hidden'));
  document.getElementById(id).classList.remove('hidden');
  document.querySelectorAll('.nav-btn').forEach(x => x.classList.remove('active'));
  if (el) el.classList.add('active');
}
function toggleChat() { document.getElementById('chatPopup').classList.toggle('open'); }
function setLang(lang) {
  currentLang = lang;
  document.getElementById('langEn').classList.toggle('active', lang === 'en');
  document.getElementById('langTa').classList.toggle('active', lang === 'ta');
}
function addBubble(text, who) {
  const body = document.getElementById('chatBody');
  const div = document.createElement('div');
  div.className = 'bubble ' + who;
  div.textContent = text;
  body.appendChild(div);
  body.scrollTop = body.scrollHeight;
}
function setMood(mood) {
  const frame = document.getElementById('assistantFrame');
  const status = document.getElementById('chatStatus');
  frame.classList.remove('happy','thoughtful','care','smile');
  frame.classList.add(mood || 'smile');
  if (mood === 'happy') status.textContent = 'Happy to help with bookings and bridal plans.';
  else if (mood === 'thoughtful') status.textContent = 'Thinking through your skin or hair details.';
  else if (mood === 'care') status.textContent = 'Providing careful guidance and caution notes.';
  else status.textContent = 'Using your uploaded assistant image with reactive styling.';
}
async function sendChat() {
  const input = document.getElementById('chatMessage');
  const message = input.value.trim();
  if (!message) return;
  addBubble(message, 'user');
  input.value = '';
  setMood('thoughtful');
  const res = await fetch('/api/chat', {
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({message:message, language:currentLang})
  });
  const data = await res.json();
  setMood(data.expression || 'smile');
  addBubble(data.reply, 'bot');
}
async function runAnalyzer(kind) {
  const score = Number(document.getElementById(kind+'Score').value || 0);
  const note = document.getElementById(kind+'Note').value || '';
  const res = await fetch('/api/analyze/'+kind, {
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({score:score, note:note})
  });
  const data = await res.json();
  const box = document.getElementById(kind+'Report');
  box.classList.remove('hidden');
  box.innerHTML = '<b>'+data.title+'</b><br/>Health Index: <b>'+data.health_index+'</b> • '+data.band+'<br/>Issues: '+data.issues.join(', ')+'<br/>Warning: '+data.warning+'<br/>Recommended Services: '+data.services.join(' • ')+'<br/>Home-care: '+data.homecare+'<br/>Customer Notes: '+(data.note||'—');
}
async function runBridal() {
  const color = document.getElementById('sareeColor').value;
  const eventTime = document.getElementById('eventTime').value;
  const mood = document.getElementById('bridalMood').value;
  const res = await fetch('/api/bridal?color='+encodeURIComponent(color)+'&event_time='+encodeURIComponent(eventTime));
  const data = await res.json();
  const box = document.getElementById('bridalReport');
  box.classList.remove('hidden');
  box.innerHTML = '<b>Bridal Saree Analysis</b><br/>Palette: '+data.palette+'<br/>Jewelry: '+data.jewelry+'<br/>Hairstyle Direction: '+data.hair+'<br/>Makeup Notes: '+data.makeup+'<br/>Style Mood: '+mood+'<br/><br/><b>3 Priority Bridal Looks</b><br/>1. '+data.looks[0]+'<br/>2. '+data.looks[1]+'<br/>3. '+data.looks[2];
}
async function loadData() {
  const incidents = await (await fetch('/api/incidents')).json();
  const legal = await (await fetch('/api/legal')).json();
  const iot = await (await fetch('/api/iot')).json();
  const certs = await (await fetch('/api/certifications')).json();
  const hairHealth = await (await fetch('/api/hair-health')).json();
  const franchise = await (await fetch('/api/franchise')).json();
  document.getElementById('incidentTable').innerHTML = '<tr><th>ID</th><th>Branch</th><th>Category</th><th>Severity</th><th>Status</th></tr>' + incidents.map(x => '<tr><td>'+x.id+'</td><td>'+x.branch+'</td><td>'+x.category+'</td><td>'+x.severity+'</td><td>'+x.status+'</td></tr>').join('');
  document.getElementById('legalList').innerHTML = legal.map(x => '<div class="item"><b>'+x.id+'</b> • '+x.topic+' • '+x.status+'</div>').join('');
  document.getElementById('iotList').innerHTML = iot.map(x => '<div class="item"><b>'+x.zone+'</b> • '+x.metric+' • '+x.status+' • '+x.value+'</div>').join('');
  document.getElementById('certList').innerHTML = certs.map(x => '<div class="item"><b>'+x.name+'</b><br/>'+x.skill+'<br/>Level: '+x.level+' • '+x.status+'</div>').join('');
  document.getElementById('hairHealthList').innerHTML = hairHealth.map(x => '<div class="item"><b>'+x.client+'</b><br/>Goal: '+x.goal+'<br/>Scalp: '+x.scalp+'<br/>Risk: '+x.risk+'<br/>Next: '+x.next+'</div>').join('');
  document.getElementById('branchTable').innerHTML = '<tr><th>Branch</th><th>Training</th><th>Quality</th><th>Revenue</th><th>Skill Gap</th></tr>' + franchise.branches.map(x => '<tr><td>'+x.branch+'</td><td>'+x.training+'</td><td>'+x.quality+'</td><td>'+x.revenue+'</td><td>'+x.skill_gap+'</td></tr>').join('');
}
document.addEventListener('DOMContentLoaded', function() {
  loadData();
  addBubble('Hello. I’m your stylist assistant. Ask about hair, skin, bridal looks, booking support, or Tamil replies.', 'bot');
  document.getElementById('chatMessage').addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      sendChat();
    }
  });
});
</script>
</body>
</html>
"""

@app.get("/", response_class=HTMLResponse)
def home():
    return HTMLResponse(HTML)

if __name__ == "__main__":
    import uvicorn
    uvicorn.run("beauty_salon_dashboard_restored:app", host="127.0.0.1", port=8000, reload=True)
